import { readFileSync } from 'node:fs'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isAlpha = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_')
const isIdent = (c) => isAlpha(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isAlpha(c)) {
      let s = ''
      while (i < n && isIdent(cs[i])) s += adv()
      tokens.push([sl, sc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const run = (ok) => {
        // returns true if at least one digit consumed
        let any = false
        while (i < n) {
          if (ok(cs[i])) { s += adv(); any = true }
          else if (any && cs[i] === '_' && ok(cs[i + 1]) && ok(cs[i - 1])) s += adv()
          else break
        }
        return any
      }
      const p = (cs[i + 1] || '').toLowerCase()
      let good = true
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        s += adv(); s += adv()
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        good = run(ok)
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { s += adv(); s += adv(); run(isDigit) }
        }
      }
      if (!good || isIdent(cs[i]) ) {
        while (i < n && isIdent(cs[i])) s += adv()
        throw new ScanError(sl, sc, 'invalid number ' + s)
      }
      tokens.push([sl, sc, 'number', s])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = cs[i]
        const bad = () => new ScanError(bl, bc, 'invalid escape \\' + e)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(simple, e)) { adv(); v += simple[e]; continue }
        if (e === 'x') {
          adv()
          let h = ''
          for (let k = 0; k < 2; k++) {
            if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
            if (!isHex(cs[i])) throw bad()
            h += adv()
          }
          v += String.fromCodePoint(parseInt(h, 16))
          continue
        }
        if (e === 'u') {
          adv()
          if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
          if (cs[i] !== '{') throw bad()
          adv()
          let h = ''
          for (;;) {
            if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
            if (cs[i] === '}' && h) { adv(); break }
            if (!isHex(cs[i])) throw bad()
            h += adv()
            if (parseInt(h, 16) > 0x10ffff) throw bad()
          }
          v += String.fromCodePoint(parseInt(h, 16))
          continue
        }
        throw bad()
      }
      tokens.push([sl, sc, 'string', JSON.stringify(v)])
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { adv(); adv(); tokens.push([sl, sc, 'punct', two]); continue }
    if (PUNCT1.has(c)) { adv(); tokens.push([sl, sc, 'punct', c]); continue }
    throw new ScanError(sl, sc, 'unexpected character ' + c)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let toks
try {
  toks = scan(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const [l, c, k, b] of toks) out += `${l}:${c} ${k} ${b}\n`
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
    out += `${k} ${toks.filter((t) => t[2] === k).length}\n`
  }
  out += `total ${toks.length}\n`
}
process.stdout.write(out)
EOF
