import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
  // ok
