class Fail extends Error {}

function count(field, text, least) {
  if (!COUNT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function parse(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        const shape = d === 'bucket' ? 5 : d === 'window' ? 4 : 3
        if (d === 'route' ? w.length < 3 : w.length !== shape) {
          throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>'
            : d === 'window' ? 'expected window <name> <limit> <span>'
            : 'expected route <prefix> <policy>...')
        }
        if (events.length > 0) throw new Fail('declarations must come before the first event')
        if (d === 'route') {
          if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
          if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
          for (const p of w.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          routes.set(w[1], w.slice(2))
        } else {
          if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
          let p
          if (d === 'bucket') {
            p = { kind: 'bucket', capacity: count('capacity', w[2], 1), refill: count('refill', w[3], 0), per: count('per', w[4], 1) }
          } else {
            p = { kind: 'window', limit: count('limit', w[2], 0), span: count('span', w[3], 1) }
          }
          if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
          p.name = w[1]
          policies.set(w[1], p)
        }
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count('tick', w[1], 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, tickText: w[1], key: w[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { policies, routes, events }
}

function run({ policies, routes, events }) {
  const states = new Map()
  const stateFor = (p, key) => {
    const id = p.name + '\0' + key
    return states.get(id) ?? (states.set(id, p.kind === 'bucket'
      ? { num: p.capacity * p.per, at: null } : { ticks: [] }), states.get(id))
  }
  const prefixes = [...routes.keys()]
  const result = []
  for (const ev of events) {
    let best = null
    for (const pre of prefixes) {
      if (ev.key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let denier = null
    if (best !== null) {
      const list = routes.get(best).map((n) => policies.get(n))
      const sts = list.map((p) => stateFor(p, ev.key))
      list.forEach((p, i) => {
        const s = sts[i]
        if (p.kind === 'bucket') {
          if (s.at !== null) {
            s.num += p.refill * (ev.tick - s.at)
            const cap = p.capacity * p.per
            if (s.num > cap) s.num = cap
          }
          s.at = ev.tick
        } else {
          const cut = ev.tick - p.span
          s.ticks = s.ticks.filter((t) => t > cut)
        }
      })
      for (let i = 0; i < list.length && denier === null; i++) {
        const p = list[i], s = sts[i]
        const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) denier = p.name
      }
      if (denier === null) {
        list.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].num -= p.per
          else sts[i].ticks.push(ev.tick)
        })
      }
    }
    result.push({ ev, denier })
  }
  return result
}

let out
try {
  const parsed = parse(readFileSync(0, 'utf8'))
  const res = run(parsed)
  out = ''
  if (mode === 'replay') {
    for (const { ev, denier } of res) {
      out += `${ev.tickText} ${ev.key} ${denier === null ? 'allow' : 'deny ' + denier}\n`
    }
  } else {
    const per = new Map()
    let a = 0, d = 0
    for (const { ev, denier } of res) {
      const c = per.get(ev.key) ?? { a: 0, d: 0 }
      if (denier === null) { c.a++; a++ } else { c.d++; d++ }
      per.set(ev.key, c)
    }
    for (const k of [...per.keys()].sort()) out += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
    out += `total allowed=${a} denied=${d}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
