    const sc = col
    const c1 = cs[i + 1]

    if (c === '/' && c1 === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && c1 === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }

    if (c === 'r' && c1 === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }

    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      tokens.push([sl, sc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }

    if (isDigit(c)) {
      let s = ''
      let bad = false
      const take = () => { s += adv() }
      // digit run with single underscores between digits
      const run = (ok) => {
        let any = false
        while (i < n) {
          if (ok(cs[i])) { take(); any = true }
          else if (cs[i] === '_' && any && ok(cs[i - 1]) && ok(cs[i + 1])) take()
