const NAME = /^[A-Za-z0-9_-]+$/

/** Parses election text into `{ candidates, ballots: [{count, names}] }`. */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const n = i + 1
    const err = (m) => new ElectionError(`error: line ${n}: ${m}`)
    const words = line.split(/\s+/)
    const word = words[0]
    if (word === 'candidates') {
      if (candidates !== null) throw err('candidates must be declared once, before any ballot')
      if (words.length < 2) throw err('expected candidates <name>...')
      const seen = new Set()
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) throw err(`invalid candidate name ${name}`)
        if (seen.has(name)) throw err(`candidate ${name} is declared twice`)
        seen.add(name)
      }
