      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return tbl
      } else throw fail('unterminated inline table')
    }
  }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new LineParser(lines[n])
      p.skipWs()
      const c = p.s[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
