        const last = names[names.length - 1]
        const full = names.join('.')
        const ex = parent.m.get(last)
        if (aot) {
          const t = newTable()
          if (ex === undefined) parent.m.set(last, { k: 'array', items: [t], aot: true })
          else if (ex.k === 'array' && ex.aot) ex.items.push(t)
          else throw fail(`${full} is not an array of tables`)
          cur = t
        } else {
          if (ex === undefined) {
            const t = newTable()
            t.hdr = true
            parent.m.set(last, t)
            cur = t
          } else if (ex.k === 'table') {
            if (ex.hdr) throw fail(`table ${full} is defined twice`)
            ex.hdr = true
            cur = ex
          } else throw fail(`${full} is not a table`)
        }
        curPath = names
        continue
      }
      const names = p.dotted()
      if (p.s[p.i] !== '=') throw fail('expected key = value')
      p.i++
      const v = p.value([...curPath, ...names])
      p.skipWs()
      if (!p.atEnd()) throw fail('trailing text after a value')
      assign(cur, names, curPath, v)
    } catch (e) {
      if (e && e.configError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
