cat > src/election.js <<'EOF'
function fail(msg) {
  const e = new Error(msg)
  e.election = true
  throw e
}

export function parse(text) {
  const raw = text.split('\n')
  if (raw[raw.length - 1] === '') raw.pop()
  let candidates = null
  const ballots = []
  raw.forEach((line, i) => {
    const n = i + 1
    line = line.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = [...seen]
    } else if (t[0] === 'ballot') {
      if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  })
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const lines = []
  for (let round = 1; ; round++) {
    const votes = new Map([...continuing].map((c) => [c, 0]))
    let active = 0
    let total = 0
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const listed = [...votes].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    lines.push(`round ${round}: ${listed.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
    if (active === 0) return { lines, winner: null, rounds: round }
    const top = listed.find(([, v]) => v * 2 > active)
    if (top) return { lines, winner: top[0], rounds: round }
    const min = Math.min(...votes.values())
    let tied = [...votes].filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; r < round && tied.length > 1; r++) {
      const m = Math.min(...tied.map((c) => history.get(c)[r]))
      tied = tied.filter((c) => history.get(c)[r] === m)
    }
    tied.sort()
    const out = tied[tied.length - 1]
    continuing.delete(out)
    lines.push(`eliminated ${out}`)
  }
}
EOF
