import { readFileSync } from 'node:fs'

class Fail extends Error {}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  const m = /^([^:/?#]+):/.exec(s)
  if (m) {
    r.scheme = m[1]
    s = s.slice(m[0].length)
  }
  if (s.startsWith('//')) {
    s = s.slice(2)
    const i = s.search(/[/?#]/)
    r.authority = i < 0 ? s : s.slice(0, i)
    s = i < 0 ? '' : s.slice(i)
  }
  const h = s.indexOf('#')
  if (h >= 0) {
    r.fragment = s.slice(h + 1)
    s = s.slice(0, h)
  }
  const q = s.indexOf('?')
  if (q >= 0) {
    r.query = s.slice(q + 1)
    s = s.slice(0, q)
  }
  r.path = s
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = at >= 0 ? a.slice(at + 1) : a
  const c = hp.indexOf(':', hp.lastIndexOf(']') + 1)
  return c >= 0
    ? { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
    : { userinfo, host: hp, port: undefined }
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    h = h.toUpperCase()
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h
  })
}

function check(name, s) {
  if (s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)) {
    throw new Fail(`the ${name} has a truncated percent-encoding`)
  }
}

function checkAll(r) {
  check('path', r.path)
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    check('userinfo', a.userinfo)
    check('host', a.host)
  }
  check('query', r.query)
  check('fragment', r.fragment)
}

function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lowerAscii(r.scheme)
  let authority
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    let s = ''
    if (a.userinfo !== undefined) s += pct(a.userinfo) + '@'
    s += pct(a.host).replace(/(%[0-9A-F]{2})|[A-Z]/g, (m, t) => (t ? t : m.toLowerCase()))
    if (a.port !== undefined && a.port !== '' && a.port !== DEFAULT_PORT[scheme]) {
      s += ':' + pct(a.port)
    }
    authority = s
  }
  let path = removeDots(pct(r.path))
  if (authority !== undefined && path === '') path = '/'
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (r.query !== undefined) out += '?' + pct(r.query)
  if (r.fragment !== undefined) out += '#' + pct(r.fragment)
  return out
}

function resolve(base, ref) {
  if (ref.scheme !== undefined) return ref
  const t = { scheme: base.scheme, authority: undefined, path: '', query: undefined, fragment: ref.fragment }
  if (ref.authority !== undefined) {
    t.authority = ref.authority
    t.path = ref.path
    t.query = ref.query
  } else {
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = ref.path
      else if (base.authority !== undefined && base.path === '') t.path = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        t.path = (i >= 0 ? base.path.slice(0, i + 1) : '') + ref.path
      }
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      const n = idx + 1
      try {
        if (mode === 'normalize') {
          const r = parse(line)
          checkAll(r)
          out.push(normalize(r))
        } else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const base = parse(line.slice(0, sp))
          if (base.scheme === undefined) throw new Fail('the base has no scheme')
          const ref = parse(line.slice(sp + 1))
          checkAll(base)
          checkAll(ref)
          out.push(normalize(resolve(base, ref)))
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${n}: ${e.message}`)
        throw e
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

main()
