const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ k: 'n', v })
const err = (v) => ({ k: 'e', v })
const bool = (v) => ({ k: 'b', v })
const text = (v) => ({ k: 's', v })

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: parseFloat(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    const two = s.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ t: 'op', v: two }); i += 2; continue }
    if ('()+-*/^=<>,:'.includes(c)) { toks.push({ t: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

// Returns {ast|null, bad, refs:[addr]} ; ast null means grammar failure.
function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return { ast: null, refs: [] }
  let p = 0
  let bad = false
  const refs = new Set()
  const fail = new Error('parse')
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const rangeAddrs = (a, b) => {
    const x = parseAddr(a), y = parseAddr(b)
    if (!x || !y) return null
    const out = []
    for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
      for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push(colName(c) + r)
    return out
  }
  const mkRange = (a, b) => {
    const list = rangeAddrs(a, b)
    if (list) list.forEach((x) => refs.add(x))
    return { n: 'range', list }
  }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw fail
    const t = toks[p++]
    if (t.t === 'num') return { n: 'num', v: t.v }
    if (t.t === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!isOp(')')) throw fail
        p++
        return e
      }
      throw fail
    }
    // word
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          const a = toks[p], b = toks[p + 1], c = toks[p + 2], d = toks[p + 3]
          if (a && a.t === 'word' && b && b.t === 'op' && b.v === ':' && c && c.t === 'word' &&
