    }
    if (isOp(':')) {
      p++
      const c = toks[p++]
      if (!c || c.t !== 'word') throw fail
      bad = true
      mkRange(t.v, c.v)
      return { n: 'num', v: 0 }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE') return { n: 'bool', v: true }
    if (u === 'FALSE') return { n: 'bool', v: false }
    const a = parseAddr(t.v)
    if (a) { refs.add(a.addr); return { n: 'ref', addr: a.addr } }
    return { n: 'badref' }
  }
  try {
    const ast = cmp()
    if (p < toks.length) throw fail
    return { ast: bad ? { n: 'err' } : ast, refs: [...refs] }
  } catch (e) {
    if (e !== fail) throw e
    return { ast: null, refs: [] }
