function sortAddrs(list) {
  return [...new Set(list)].map((a) => parseAddr(a)).sort((x, y) => x.col - y.col || x.row - y.row).map((a) => a.addr)
}

export function depsOf(cell) {
  if (cell.content[0] !== '=') return []
  return sortAddrs(parseFormula(cell.content.slice(1)).refs)
}

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }

export function evaluateAll(cells) {
  const byAddr = new Map(cells.map((c) => [c.addr, c]))
  const memo = new Map()
  const active = new Set()

  function literal(content) {
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(parseFloat(content))
    if (ERRS.includes(content)) return err(content)
    return text(content)
  }

  function cellValue(addr) {
    const cell = byAddr.get(addr)
    if (!cell) return num(0)
    if (memo.has(addr)) return memo.get(addr)
    if (active.has(addr)) return err('#CYCLE!')
    let v
    if (cell.content[0] === '=') {
      active.add(addr)
      const { ast } = parseFormula(cell.content.slice(1))
      v = ast ? ev(ast) : err('#ERR!')
      active.delete(addr)
    } else v = literal(cell.content)
    memo.set(addr, v)
    return v
  }

  const toNum = (v) => {
    if (v.k === 'n') return v
    if (v.k === 'b') return num(v.v ? 1 : 0)
    if (v.k === 'e') return v
    return err('#VALUE!')
  }
  const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

  function rangeValues(list) {
    if (!list) return null
    return list.map(cellValue)
  }

  function call(node) {
    const { name, args } = node
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'ABS' && args.length !== 1) return err('#ERR!')
    if (name === 'IF' && args.length !== 3) return err('#ERR!')
    if (args.length < 1) return err('#ERR!')
    if (name === 'IF') {
      if (args.some((a) => a.n === 'range')) return err('#ERR!')
      const c = ev(args[0])
      if (c.k === 'e') return c
      let truth
      if (c.k === 'b') truth = c.v
      else if (c.k === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? args[1] : args[2])
    }
    const vals = []
    for (const a of args) {
      if (a.n === 'range') {
        const l = rangeValues(a.list)
        if (!l) return err('#REF!')
        vals.push(...l)
      } else vals.push(ev(a))
    }
    const firstErr = vals.find((v) => v.k === 'e')
    if (firstErr) return firstErr
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
    if (name === 'ABS') {
      if (args[0].n === 'range') return err('#ERR!')
      const n = toNum(vals[0])
      return n.k === 'e' ? n : finite(Math.abs(n.v))
    }
    const nums = []
    for (const v of vals) {
      const n = toNum(v)
      if (n.k === 'e') return n
      nums.push(n.v)
    }
    if (name === 'SUM') return finite(nums.reduce((a, b) => a + b, 0))
    if (name === 'AVG') return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
    if (name === 'MIN') return num(Math.min(...nums))
    return num(Math.max(...nums))
  }

  function ev(node) {
    switch (node.n) {
      case 'num': return num(node.v)
      case 'bool': return bool(node.v)
      case 'err': return err('#ERR!')
      case 'badref': return err('#REF!')
      case 'ref': return cellValue(node.addr)
      case 'call': return call(node)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(ev(node.e))
        if (v.k === 'e') return v
        return num(node.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = ev(node.l), r = ev(node.r)
        if (['=', '<>', '<', '<=', '>', '>='].includes(node.op)) {
          if (l.k === 'e') return l
          if (r.k === 'e') return r
          let d
          if (l.k !== r.k) d = rank[l.k] - rank[r.k]
          else if (l.k === 's') d = cpCompare(l.v, r.v)
          else if (l.k === 'b') d = Number(l.v) - Number(r.v)
          else d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
          const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[node.op]
          return bool(res)
        }
        const a = toNum(l)
        if (a.k === 'e') return a
        const b = toNum(r)
        if (b.k === 'e') return b
        switch (node.op) {
          case '+': return finite(a.v + b.v)
          case '-': return finite(a.v - b.v)
          case '*': return finite(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
          default: return finite(Math.pow(a.v, b.v))
        }
      }
    }
    return err('#ERR!')
  }

  const out = new Map()
  for (const c of cells) out.set(c.addr, cellValue(c.addr))
  return out
}

export function formatValue(v) {
  if (v.k === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}
