export function colIndex(letters) {
  const u = letters.toUpperCase()
  if (u.length === 1) return u.charCodeAt(0) - 64
  return 26 + (u.charCodeAt(0) - 65) * 26 + (u.charCodeAt(1) - 64)
}

export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}

// Returns {col,row,addr} or null.
export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colIndex(m[1])
  return { col, row, addr: colName(col) + row }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
