    const a = parseAddr(word)
    if (!a) throw new SheetError(`error: line ${i + 1}: invalid cell address ${word}`)
    if (seen.has(a.addr)) throw new SheetError(`error: line ${i + 1}: cell ${a.addr} is declared twice`)
    seen.add(a.addr)
    cells.push({ addr: a.addr, col: a.col, row: a.row, content: m[2] })
  })
  cells.sort((x, y) => x.col - y.col || x.row - y.row)
  return cells
}
