      if (d === 'event' && t.length !== 3) throw new Fail('expected event <tick> <key>')
      if (decl && events.length) throw new Fail('declarations must come before the first event')
      if (d === 'bucket' || d === 'window') {
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = num(t[2], 'capacity', 1)
          const refill = num(t[3], 'refill', 0)
          const per = num(t[4], 'per', 1)
          p = { kind: 'bucket', name: t[1], capacity, refill, per }
        } else {
          p = { kind: 'window', name: t[1], limit: num(t[2], 'limit', 0), span: num(t[3], 'span', 1) }
        }
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], p)
      } else if (d === 'route') {
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        for (const n of t.slice(2)) if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        routes.set(t[1], t.slice(2).map((n) => policies.get(n)))
      } else {
        const tick = num(t[1], 'tick', 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: t[2] })
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map()
  const out = []
  const counts = new Map()
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, list] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
    }
    let denier = null
    if (best) {
      const sts = best.list.map((p) => {
        const id = p.name + '\0' + key
        let s = states.get(id)
        if (!s) {
          s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
          states.set(id, s)
        }
        if (p.kind === 'bucket') {
          s.num += p.refill * (tick - s.last)
          s.last = tick
          const cap = p.capacity * p.per
          if (s.num > cap) s.num = cap
        } else {
          s.ticks = s.ticks.filter((x) => x > tick - p.span)
        }
        return s
      })
      for (let i = 0; i < sts.length; i++) {
        const p = best.list[i]
        const ok = p.kind === 'bucket' ? sts[i].num >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) { denier = p; break }
      }
      if (!denier) {
        sts.forEach((s, i) => {
          const p = best.list[i]
          if (p.kind === 'bucket') s.num -= p.per
          else s.ticks.push(tick)
        })
      }
    }
    const c = counts.get(key) ?? { a: 0, d: 0 }
    if (denier) c.d++; else c.a++
    counts.set(key, c)
    out.push(denier ? `${tick} ${key} deny ${denier.name}` : `${tick} ${key} allow`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let a = 0, d = 0, s = ''
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const c = counts.get(k)
    a += c.a; d += c.d
    s += `${k} allowed=${c.a} denied=${c.d}\n`
  }
  return s + `total allowed=${a} denied=${d}\n`
}

try {
  const result = run(parse(readFileSync(0, 'utf8')))
  process.stdout.write(result)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
