test('a change only one side made is taken', () => {
  assert.deepEqual(run(['merge'], ['a', 'X'], ['a', 'b'], ['a', 'b']), { code: 0, out: 'a\nX\n', err: '' })
})

test('a change only the other side made is taken', () => {
  assert.equal(run(['merge'], ['a', 'b'], ['a', 'b'], ['a', 'Z']).out, 'a\nZ\n')
