function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
    L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, cs = null
  const close = () => { if (cs) { res.push({ who, bs: cs[0], be: i, ss: cs[1], se: j }); cs = null } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { close(); i++; j++; continue }
    if (!cs) cs = [i, j]
    if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  close()
  return res
}

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const sides = [mine, theirs]
  const out = []
  let pos = 0, k = 0
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) { end = Math.max(end, all[k].be); group.push(all[k++]) }
    if (start > pos) out.push({ kind: 'stable', lines: base.slice(pos, start) })
    pos = end
    const baseL = base.slice(start, end)
    const rep = who => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return baseL
      const ms = Math.min(...g.map(c => c.bs)), me = Math.max(...g.map(c => c.be))
      const s = Math.min(...g.map(c => c.ss)), e = Math.max(...g.map(c => c.se))
      return sides[who].slice(s - (ms - start), e + (end - me))
    }
    const m = rep(0), t = rep(1)
    const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
    if (group.length === 1) out.push({ kind: group[0].who ? 'theirs' : 'mine', lines: group[0].who ? t : m })
    else if (eq(m, t)) out.push({ kind: 'both', lines: m })
    else if (eq(m, baseL)) out.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseL)) out.push({ kind: 'mine', lines: m })
    else out.push({ kind: 'conflict', mine: m, base: baseL, theirs: t })
  }
  if (pos < base.length) out.push({ kind: 'stable', lines: base.slice(pos) })
  return out
}
