{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

class Table { constructor() { this.map = new Map(); this.header = false } }
class Arr { constructor(aot) { this.items = []; this.aot = aot } }
class Scalar { constructor(type, value) { this.type = type; this.value = value } }

const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

class Parser {
  constructor(line) { this.s = line; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  basic() {
    const s = this.s
    let i = this.i + 1
    let out = ''
    for (;;) {
      const c = s[i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.i = i + 1; return out }
      if (c === '\\') {
        const e = s[i + 1]
        if (e === undefined) fail('unterminated string')
        const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(m, e)) { out += m[e]; i += 2; continue }
        if (e === 'u') {
          const h = s.slice(i + 2, i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          i += 6
          continue
        }
        fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(i + 1)))
      }
      out += c
      i++
    }
  }
  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isNameCh(c)) fail('expected a name')
    const st = this.i
    while (isNameCh(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; return parts }
    }
  }

  value(prefix) {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return new Scalar('string', this.basic())
    if (c === "'") return new Scalar('string', this.literal())
    if (c === '[') {
      this.i++
      const arr = new Arr(false)
      for (;;) {
        this.ws()
        if (this.s[this.i] === ']') { this.i++; return arr }
        arr.items.push(this.value(prefix))
        this.ws()
        const d = this.s[this.i]
        if (d === ',') { this.i++; continue }
        if (d === ']') { this.i++; return arr }
        fail('unterminated array')
      }
    }
    if (c === '{') {
      this.i++
      const t = new Table()
      this.ws()
      if (this.s[this.i] === '}') { this.i++; return t }
      for (;;) {
        this.ws()
        const keys = this.dotted()
        this.ws()
        if (this.s[this.i] !== '=') fail('expected = in an inline table')
        this.i++
        const v = this.value(prefix)
        assign(t, prefix, keys, v)
        this.ws()
        const d = this.s[this.i]
        if (d === ',') { this.i++; continue }
        if (d === '}') { this.i++; return t }
        fail('unterminated inline table')
      }
    }
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true' || tok === 'false') return new Scalar('boolean', tok === 'true')
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(tok)) return new Scalar('integer', BigInt(tok.replace(/_/g, '')).toString())
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(tok)) {
      return new Scalar('float', Number(tok.replace(/_/g, '')))
