import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) { super(msg); this.code = code }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const deps = []
  const nameRe = /^[A-Za-z0-9_.\-]+$/
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!nameRe.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const dm = new Map()
  for (const k of tasks.keys()) dm.set(k, new Set())
  for (const d of deps) for (const x of d) if (!tasks.has(x)) throw new Fail(`error: unknown task ${x}`)
  for (const [a, ...rest] of deps) for (const b of rest) dm.get(a).add(b)
  const names = [...tasks.keys()].sort()
  const dl = new Map(names.map((k) => [k, [...dm.get(k)].sort()]))
  return { tasks, names, dl }
}

function findCycle({ names, dl }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      if (state.get(v) === 1) return [...stack.slice(stack.indexOf(v)), v]
      if (!state.has(v)) { const c = visit(v); if (c) return c }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }
  for (const s of names) if (!state.has(s)) { const c = visit(s); if (c) return c }
  return null
}

function analyze(g) {
  const info = new Map()
  const go = (u) => {
    if (info.has(u)) return info.get(u)
    let start = 0n, depth = 0
    for (const d of g.dl.get(u)) {
      const i = go(d)
      if (i.finish > start) start = i.finish
      if (i.depth + 1 > depth) depth = i.depth + 1
    }
    const r = { start, finish: start + g.tasks.get(u), depth }
    info.set(u, r)
    return r
  }
  g.names.forEach(go)
  let total = 0n
  for (const i of info.values()) if (i.finish > total) total = i.finish
  return { info, total }
}

function pack(g, workers) {
  const rev = new Map(g.names.map((k) => [k, []]))
  for (const [k, ds] of g.dl) for (const d of ds) rev.get(d).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let best = 0n
    for (const v of rev.get(u)) { const p = pr(v); if (p > best) best = p }
    const r = best + g.tasks.get(u)
    prio.set(u, r)
    return r
  }
  g.names.forEach(pr)
  const finish = new Map()
  const free = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let remaining = g.names.length
  let t = 0n
  let makespan = 0n
  while (remaining > 0) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const u of g.names) {
        if (finish.has(u)) continue
        if (!g.dl.get(u).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (pick === null || prio.get(u) > prio.get(pick)) pick = u
      }
      if (pick === null) break
      const f = t + g.tasks.get(pick)
      finish.set(pick, f)
      free[w] = f
      runs[w].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    for (const f of finish.values()) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  const out = runs.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}`)
  out.push(`makespan ${makespan}`)
  return out.join('\n') + '\n'
}

function main() {
  const args = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let mode, workers
  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) mode = args[0]
  else if (args.length === 2 && args[0] === 'pack') {
    mode = 'pack'
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(args[1])
  } else throw new Fail(usage)
  const g = parse(readFileSync(0, 'utf8'))
  const cyc = findCycle(g)
  if (cyc) throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
  if (mode === 'pack') return pack(g, workers)
  const { info, total } = analyze(g)
  const out = []
  if (mode === 'waves') {
    const waves = []
    for (const n of g.names) (waves[info.get(n).depth] ??= []).push(n)
    waves.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
  } else {
    for (const n of g.names) {
      const i = info.get(n)
      out.push(`${n} start=${i.start} finish=${i.finish} depth=${i.depth}`)
    }
  }
  out.push(`total ${total}`)
  return out.join('\n') + '\n'
}

try {
  process.stdout.write(main())
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
