  }
  m = /^[^?#]*/.exec(s)
  r.path = m[0]
  s = s.slice(m[0].length)
  if (s.startsWith('?')) {
    m = /^\?([^#]*)/.exec(s)
    r.query = m[1]
    s = s.slice(m[0].length)
  }
  if (s.startsWith('#')) r.fragment = s.slice(1)
  return r
}

function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  let host = rest, port
  if (colon >= 0) { host = rest.slice(0, colon); port = rest.slice(colon + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path, out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRESERVED = /^[A-Za-z0-9\-._~]$/
const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
