// Returns {error: component} or {text}.
export function normalize(r) {
  const parts = r.authority === undefined ? { userinfo: undefined, host: undefined, port: undefined } : splitAuthority(r.authority)
  const checks = [['path', r.path], ['userinfo', parts.userinfo], ['host', parts.host], ['query', r.query], ['fragment', r.fragment]]
  for (const [name, v] of checks) if (v !== undefined && truncated(v)) return { error: name }
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (r.authority !== undefined) {
    out += '//'
    if (parts.userinfo !== undefined) out += pct(parts.userinfo) + '@'
    out += lower(pct(parts.host))
    let port = parts.port
    if (port === '' || (scheme !== undefined && port === DEFAULT_PORTS[scheme])) port = undefined
    if (port !== undefined) out += ':' + port
  }
  let path = removeDots(pct(r.path))
  if (r.authority !== undefined && path === '') path = '/'
  out += path
  if (r.query !== undefined) out += '?' + pct(r.query)
  if (r.fragment !== undefined) out += '#' + pct(r.fragment)
  return { text: out }
}

export function resolve(base, ref) {
  const t = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: ref.fragment }
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}
